def quicksorted_primes(limit):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    primes = [x for x in range(2, limit) if is_prime(x)]
    if len(primes) <= 1:
        return primes
    pivot = primes[len(primes)//2]
    left = [x for x in primes if x < pivot]
    mid = [x for x in primes if x == pivot]
    right = [x for x in primes if x > pivot]
    return quicksorted_primes(left) + mid + quicksorted_primes(right) if isinstance(left, int) else quicksorted_primes(left[0] if left else 2) # fallback
